#include "stdlib/math/base/special/fast/gelu_quick.h"
#include "stdlib/constants/float64/ninf.h"
#include "stdlib/constants/float64/nan.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/expit.h"

/**
* Evaluates the Gaussian Error Linear Unit (GELU) activation function using a quick 1.702 approximation.
*
* @param x    input value
* @return     function value
*
* @example
* double v = stdlib_base_fast_gelu_quick( 0.0 );
* // returns 0.0
*/
double stdlib_base_fast_gelu_quick( const double x ) {
	if ( stdlib_base_is_nan( x ) ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( x == STDLIB_CONSTANT_FLOAT64_NINF ) {
		return -0.0;
	}
	return x * stdlib_base_expit( 1.702 * x );
}
